sp_widget.client_script:
api.controller = function($scope, $http) {

    var c = this;


    // ==========================================
    // ACTIVE SECTION
    // ==========================================

    c.activeSection = 'dashboard';


    // ==========================================
    // COMPLAINT FORM
    // ==========================================

    c.complaintForm = {

        use_case: '',
        mess_hall: '',
        meal_type: '',
        problem_type: '',
        description: ''

    };


    c.complaintSubmitted = false;

    c.complaintSubmitting = false;

    c.complaintError = '';

    c.complaintNumber = '';

    c.complaintSysId = '';


    // ==========================================
    // FEEDBACK FORM
    // ==========================================

    c.feedbackForm = {

        overall_rating: '',

        resolution_satisfaction: '',

        feedback_comments: ''

    };


    // ==========================================
    // SELECTED FEEDBACK
    // ==========================================

    c.data.selectedFeedback = null;

    c.data.selectedFeedbackSysId = null;


    // ==========================================
    // SECTION NAVIGATION
    // ==========================================

    c.selectSection = function(section) {

        c.activeSection = section;

        c.complaintError = '';

    };


    // ==========================================
    // SUBMIT COMPLAINT
    // ==========================================

    c.submitComplaint = function() {

        c.complaintError = '';

        c.complaintSubmitting = true;


        c.server.get({

            action: 'createComplaint',

            use_case:
                c.complaintForm.use_case,

            mess_hall:
                c.complaintForm.mess_hall,

            meal_type:
                c.complaintForm.meal_type,

            problem_type:
                c.complaintForm.problem_type,

            description:
                c.complaintForm.description

        }).then(function(response) {

            c.complaintSubmitting = false;


            if (
                response.data.success
            ) {

                c.complaintSubmitted = true;

                c.complaintNumber =
                    response.data.complaintNumber;

                c.complaintSysId =
                    response.data.complaintSysId;


                // ==================================
                // FILE UPLOAD
                // ==================================

                var fileInput =
                    document.getElementById(
                        'complaintDocument'
                    );


                if (
                    fileInput &&
                    fileInput.files &&
                    fileInput.files.length > 0
                ) {

                    var file =
                        fileInput.files[0];

                    var formData =
                        new FormData();

                    formData.append(
                        'file',
                        file
                    );


                    var attachmentUrl =
                        '/api/now/attachment/file' +
                        '?table_name=' +
                        'x_snc_campus_foo_1_food_complaint' +
                        '&table_sys_id=' +
                        c.complaintSysId +
                        '&file_name=' +
                        encodeURIComponent(
                            file.name
                        );


                    $http({

                        method: 'POST',

                        url: attachmentUrl,

                        data: formData,

                        transformRequest:
                            angular.identity,

                        headers: {

                            'Content-Type':
                                undefined

                        }

                    });

                }


                c.server.update();


            } else {

                c.complaintError =
                    response.data.message ||
                    'Unable to submit complaint.';

            }


        }, function() {

            c.complaintSubmitting = false;

            c.complaintError =
                'Something went wrong. Please try again.';

        });

    };


    // ==========================================
    // NEW COMPLAINT
    // ==========================================

    c.newComplaint = function() {

        c.complaintForm = {

            use_case: '',
            mess_hall: '',
            meal_type: '',
            problem_type: '',
            description: ''

        };


        c.complaintSubmitted = false;

        c.complaintSubmitting = false;

        c.complaintError = '';

        c.complaintNumber = '';

        c.complaintSysId = '';


        var fileInput =
            document.getElementById(
                'complaintDocument'
            );


        if (fileInput) {

            fileInput.value = '';

        }

    };


    // ==========================================
    // OPEN FEEDBACK
    // ==========================================

    c.openFeedback = function(sysId) {


        // ======================================
        // GET EXACT RECORD
        // ======================================

        var feedback =
            c.data.feedbacks[sysId];


        if (!feedback) {

            return;

        }


        // ======================================
        // SAVE SYS ID
        // ======================================

        c.data.selectedFeedbackSysId =
            sysId;


        // ======================================
        // SAVE SELECTED RECORD
        // ======================================

        c.data.selectedFeedback =
            feedback;


        // ======================================
        // LOAD EXISTING VALUES
        // ======================================

        c.feedbackForm = {

            overall_rating:
                feedback.overall_rating || '',

            resolution_satisfaction:
                feedback.resolution_satisfaction || '',

            feedback_comments:
                feedback.feedback_comments || ''

        };

    };


    // ==========================================
    // SUBMIT FEEDBACK
    // ==========================================

    c.submitFeedback = function() {


        // ======================================
        // CHECK REQUIRED FIELDS
        // ======================================

        if (
            !c.feedbackForm.overall_rating ||
            !c.feedbackForm.resolution_satisfaction
        ) {

            alert(
                'Please select Overall Rating and Resolution Satisfaction.'
            );

            return;

        }


        // ======================================
        // CHECK SYS ID
        // ======================================

        if (
            !c.data.selectedFeedbackSysId
        ) {

            alert(
                'Feedback record not selected.'
            );

            return;

        }


        // ======================================
        // SEND TO SERVER
        // ======================================

        c.server.get({

            action: 'submitFeedback',

            feedbackSysId:
                c.data.selectedFeedbackSysId,

            overall_rating:
                c.feedbackForm.overall_rating,

            resolution_satisfaction:
                c.feedbackForm.resolution_satisfaction,

            feedback_comments:
                c.feedbackForm.feedback_comments

        }).then(function(response) {


            // ==================================
            // SUCCESS
            // ==================================

            if (
                response.data.feedbackSuccess
            ) {

                alert(
                    'Feedback submitted successfully.'
                );


                // ==============================
                // CLEAR SELECTED RECORD
                // ==============================

                c.data.selectedFeedback =
                    null;


                c.data.selectedFeedbackSysId =
                    null;


                // ==============================
                // CLEAR FORM
                // ==============================

                c.feedbackForm = {

                    overall_rating: '',

                    resolution_satisfaction: '',

                    feedback_comments: ''

                };


                // ==============================
                // REFRESH SERVER DATA
                // ==============================

                c.server.update();


            } else {


                alert(
                    response.data.feedbackMessage ||
                    'Unable to submit feedback.'
                );

            }

        }, function() {


            alert(
                'Something went wrong while submitting feedback.'
            );

        });

    };


    // ==========================================
    // CLOSE FEEDBACK
    // ==========================================

    c.closeFeedback = function() {


        c.data.selectedFeedback =
            null;


        c.data.selectedFeedbackSysId =
            null;


        c.feedbackForm = {

            overall_rating: '',

            resolution_satisfaction: '',

            feedback_comments: ''

        };

    };

};

sp_widget.css:
/* =========================================================
   STUDENT DASHBOARD
   ========================================================= */

.student-dashboard {
    display: flex;
    width: 100%;
    min-height: 100vh;
    background: #f5f7fa;
    font-family: Arial, sans-serif;
    color: #172033;
}


/* =========================================================
   SIDEBAR
   ========================================================= */

.student-sidebar {
    width: 230px;
    min-width: 230px;
    background: #172033;
    color: #ffffff;
    min-height: 100vh;
    padding: 0;
    box-sizing: border-box;
}

.sidebar-title {
    font-size: 20px;
    font-weight: 700;
    padding: 25px 20px;
    border-bottom: 1px solid rgba(255,255,255,0.10);
}

.sidebar-item {
    padding: 15px 20px;
    font-size: 14px;
    cursor: pointer;
    color: #cbd5e1;
    transition: 0.2s;
}

.sidebar-item:hover {
    background: #243047;
    color: #ffffff;
}

.sidebar-item.active {
    background: #0d9488;
    color: #ffffff;
    font-weight: 600;
}


/* =========================================================
   MAIN
   ========================================================= */

.student-main {
    flex: 1;
    min-width: 0;
    padding: 30px;
    box-sizing: border-box;
}


/* =========================================================
   PAGE HEADER
   ========================================================= */

.page-header {
    display: flex;
    justify-content: space-between;
    align-items: center;
    margin-bottom: 25px;
}

.page-header h1 {
    margin: 0 0 6px 0;
    font-size: 28px;
    font-weight: 700;
    color: #172033;
}

.page-header p {
    margin: 0;
    color: #64748b;
    font-size: 14px;
}


/* =========================================================
   KPI CARDS
   ========================================================= */

.kpi-grid {
    display: grid;
    grid-template-columns: repeat(3, 1fr);
    gap: 20px;
    margin-bottom: 25px;
}

.kpi-card {
    background: #ffffff;
    border-radius: 10px;
    padding: 22px;
    display: flex;
    align-items: center;
    gap: 15px;
    border: 1px solid #e5e7eb;
    box-sizing: border-box;
}

.kpi-icon {
    width: 50px;
    height: 50px;
    border-radius: 8px;
    background: #ecfdf5;
    display: flex;
    align-items: center;
    justify-content: center;
    font-size: 23px;
}

.kpi-card h3 {
    margin: 0 0 5px 0;
    font-size: 24px;
    color: #172033;
}

.kpi-card p {
    margin: 0;
    font-size: 13px;
    color: #64748b;
}


/* =========================================================
   DASHBOARD CARD
   ========================================================= */

.dashboard-card {
    width: 100%;
    background: #ffffff;
    border: 1px solid #e5e7eb;
    border-radius: 10px;
    padding: 22px;
    box-sizing: border-box;
    margin-bottom: 25px;
    overflow: hidden;
}

.card-header {
    display: flex;
    justify-content: space-between;
    align-items: center;
    margin-bottom: 20px;
    gap: 15px;
}

.card-header h2 {
    margin: 0;
    font-size: 18px;
    font-weight: 600;
    color: #172033;
}

.card-header strong {
    color: #0d9488;
}


/* =========================================================
   NORMAL TABLE
   ========================================================= */

.table-container {
    width: 100%;
    overflow-x: auto;
}

.table-container table {
    width: 100%;
    border-collapse: collapse;
    border-spacing: 0;
    background: #ffffff;
}

.table-container table th {
    padding: 13px 15px;
    background: #f8fafc;
    color: #374151;
    font-size: 13px;
    font-weight: 600;
    text-align: left;
    border-bottom: 1px solid #e2e8f0;
    white-space: nowrap;
}

.table-container table td {
    padding: 13px 15px;
    color: #475569;
    font-size: 13px;
    border-bottom: 1px solid #edf0f4;
    vertical-align: middle;
}

.table-container table tbody tr:hover {
    background: #f8fafc;
}


/* =========================================================
   STATUS
   ========================================================= */

.status-badge {
    display: inline-block;
    padding: 5px 10px;
    border-radius: 20px;
    background: #ecfdf5;
    color: #047857;
    font-size: 12px;
    font-weight: 600;
    white-space: nowrap;
}


/* =========================================================
   PRIORITY
   ========================================================= */

.priority-badge {
    display: inline-block;
    padding: 5px 10px;
    border-radius: 20px;
    background: #fff7ed;
    color: #c2410c;
    font-size: 12px;
    font-weight: 600;
}


/* =========================================================
   NO DATA
   ========================================================= */

.no-data {
    text-align: center !important;
    padding: 30px !important;
    color: #94a3b8 !important;
}


/* =========================================================
   PLACEHOLDER
   ========================================================= */

.placeholder-section {
    background: #ffffff;
    border: 1px solid #e5e7eb;
    border-radius: 10px;
    padding: 40px;
    text-align: center;
    color: #64748b;
}


/* =========================================================
   FORM
   ========================================================= */

.form-group {
    width: 100%;
    margin-bottom: 20px;
}

.form-group label {
    display: block;
    margin-bottom: 7px;
    font-size: 14px;
    font-weight: 600;
    color: #374151;
}

.form-control {
    display: block;
    width: 100%;
    min-height: 42px;
    padding: 10px 12px;
    box-sizing: border-box;
    border: 1px solid #d9dee8;
    border-radius: 7px;
    background: #ffffff;
    color: #374151;
    font-size: 14px;
    font-family: inherit;
    outline: none;
}

.form-control:focus {
    border-color: #0d9488;
    box-shadow: 0 0 0 2px rgba(13,148,136,0.10);
}

.description-field {
    min-height: 130px;
    resize: vertical;
    line-height: 1.5;
}

.file-control {
    display: block;
    width: 100%;
    padding: 9px;
    box-sizing: border-box;
    border: 1px solid #d9dee8;
    border-radius: 7px;
    background: #ffffff;
    color: #475569;
}


/* =========================================================
   COMPLAINT BUTTON
   ========================================================= */

.submit-button {
    border: none;
    background: #0d9488;
    color: #ffffff;
    padding: 12px 25px;
    border-radius: 7px;
    cursor: pointer;
    font-size: 14px;
    font-weight: 600;
}

.submit-button:hover {
    background: #0f766e;
}

.submit-button:disabled {
    opacity: 0.6;
    cursor: not-allowed;
}


/* =========================================================
   ERROR
   ========================================================= */

.error-message {
    margin-bottom: 15px;
    padding: 12px 15px;
    border-radius: 7px;
    background: #fef2f2;
    color: #b91c1c;
    border: 1px solid #fecaca;
    font-size: 14px;
}


/* =========================================================
   SUCCESS CARD
   ========================================================= */

.success-card {
    background: #ffffff;
    border: 1px solid #d1fae5;
    border-radius: 10px;
    padding: 40px;
    text-align: center;
}

.success-icon {
    width: 60px;
    height: 60px;
    margin: 0 auto 20px auto;
    border-radius: 50%;
    background: #d1fae5;
    color: #047857;
    display: flex;
    align-items: center;
    justify-content: center;
    font-size: 30px;
    font-weight: 700;
}

.success-card h2 {
    margin: 0 0 10px 0;
    color: #172033;
    font-size: 22px;
}

.success-card p {
    margin: 0 0 20px 0;
    color: #64748b;
}

.complaint-number {
    margin-bottom: 20px;
    color: #475569;
}

.complaint-number strong {
    color: #0d9488;
}

.new-complaint-button {
    border: none;
    background: #0d9488;
    color: #ffffff;
    padding: 11px 20px;
    border-radius: 7px;
    cursor: pointer;
    font-size: 14px;
    font-weight: 600;
}

.new-complaint-button:hover {
    background: #0f766e;
}


/* =========================================================
   FEEDBACK SECTION
   ========================================================= */

.feedback-details-section {
    width: 100%;
    margin-bottom: 30px;
    box-sizing: border-box;
}

.feedback-form-row {
    display: flex;
    width: 100%;
    gap: 20px;
    margin-bottom: 20px;
    box-sizing: border-box;
}

.feedback-form-group {
    flex: 1;
    width: 100%;
    margin-bottom: 20px;
    box-sizing: border-box;
}

.feedback-form-group label {
    display: block;
    margin-bottom: 7px;
    color: #374151;
    font-size: 14px;
    font-weight: 600;
}

.feedback-required {
    color: #d32f2f;
    margin-left: 3px;
}


/* =========================================================
   FEEDBACK INPUT CONTROLS
   ========================================================= */

.feedback-form-control {
    display: block !important;
    width: 100% !important;
    min-height: 42px !important;
    padding: 10px 12px !important;
    box-sizing: border-box !important;
    border: 1px solid #d9dee8 !important;
    border-radius: 7px !important;
    background: #ffffff !important;
    color: #374151 !important;
    font-size: 14px !important;
    font-family: inherit !important;
    outline: none !important;
}

.feedback-form-control:focus {
    border-color: #0d9488 !important;
    box-shadow: 0 0 0 2px rgba(13,148,136,0.10) !important;
}

.feedback-form-control[readonly] {
    background: #f1f5f9 !important;
    color: #64748b !important;
    cursor: not-allowed;
}

.feedback-textarea {
    min-height: 120px !important;
    resize: vertical !important;
    line-height: 1.5 !important;
}


/* =========================================================
   FEEDBACK INPUT AREA
   ========================================================= */

.feedback-input-section {
    width: 100%;
    border-top: 1px solid #e2e8f0;
    padding-top: 25px;
    box-sizing: border-box;
}

.feedback-input-section h3 {
    margin: 0 0 20px 0;
    font-size: 18px;
    font-weight: 600;
    color: #172033;
}

.feedback-submit-area {
    width: 100%;
    margin-top: 20px;
}


/* =========================================================
   FEEDBACK BUTTONS
   ========================================================= */

.feedback-action-button {
    display: inline-block !important;
    border: none !important;
    background: #0d9488 !important;
    color: #ffffff !important;
    padding: 8px 14px !important;
    border-radius: 6px !important;
    cursor: pointer !important;
    font-size: 13px !important;
    font-weight: 600 !important;
    white-space: nowrap !important;
    line-height: normal !important;
}

.feedback-action-button:hover {
    background: #0f766e !important;
}

.feedback-back-button {
    display: inline-block;
    border: none;
    background: #f1f5f9;
    color: #475569;
    padding: 8px 15px;
    border-radius: 6px;
    cursor: pointer;
    font-size: 13px;
    font-weight: 500;
}

.feedback-back-button:hover {
    background: #e2e8f0;
}

.feedback-submit-button {
    display: inline-block;
    border: none;
    background: #0d9488;
    color: #ffffff;
    padding: 12px 25px;
    border-radius: 7px;
    cursor: pointer;
    font-size: 14px;
    font-weight: 600;
}

.feedback-submit-button:hover {
    background: #0f766e;
}


/* =========================================================
   FEEDBACK TABLE
   IMPORTANT:
   These selectors are more specific than the normal
   table/th/td CSS above.
   ========================================================= */

.feedback-table-container {
    display: block;
    width: 100%;
    overflow-x: auto;
    overflow-y: hidden;
    box-sizing: border-box;
    -webkit-overflow-scrolling: touch;
}

.feedback-table-container .feedback-table {
    width: 100%;
    min-width: 1400px;
    border-collapse: collapse !important;
    border-spacing: 0 !important;
    background: #ffffff;
    table-layout: auto;
}


/* FEEDBACK TABLE HEADER */

.feedback-table-container .feedback-table thead tr th {
    padding: 13px 15px !important;
    background: #f8fafc !important;
    color: #374151 !important;
    font-size: 13px !important;
    font-weight: 600 !important;
    text-align: left !important;
    border-bottom: 1px solid #e2e8f0 !important;
    white-space: nowrap !important;
    vertical-align: middle !important;
}


/* FEEDBACK TABLE BODY */

.feedback-table-container .feedback-table tbody tr td {
    padding: 13px 15px !important;
    background: #ffffff;
    color: #475569 !important;
    font-size: 13px !important;
    border-bottom: 1px solid #edf0f4 !important;
    vertical-align: middle !important;
    white-space: nowrap !important;
}


/* HOVER */

.feedback-table-container .feedback-table tbody tr:hover td {
    background: #f8fafc !important;
}


/* FEEDBACK NUMBER */

.feedback-table-container .feedback-number {
    color: #0f766e !important;
    font-weight: 600 !important;
}


/* RATING */

.feedback-table-container .feedback-rating {
    color: #374151 !important;
    font-weight: 600 !important;
    text-align: center;
}


/* COMMENTS */

.feedback-table-container .feedback-comment-cell {
    max-width: 250px !important;
    width: 250px !important;
    overflow: hidden !important;
    text-overflow: ellipsis !important;
    white-space: nowrap !important;
}


/* STATUS INSIDE FEEDBACK TABLE */

.feedback-table-container .status-badge {
    display: inline-block !important;
    padding: 5px 10px !important;
    border-radius: 20px !important;
    background: #ecfdf5 !important;
    color: #047857 !important;
    font-size: 12px !important;
    font-weight: 600 !important;
    white-space: nowrap !important;
}


/* ACTION COLUMN */

.feedback-table-container .feedback-action-button {
    margin: 0 !important;
}


/* =========================================================
   FEEDBACK FORM CARD
   ========================================================= */

.feedback-form-card {
    width: 100%;
    box-sizing: border-box;
}


/* =========================================================
   RESPONSIVE
   ========================================================= */

@media (max-width: 900px) {

    .student-sidebar {
        width: 190px;
        min-width: 190px;
    }

    .student-main {
        padding: 20px;
    }

    .kpi-grid {
        grid-template-columns: 1fr;
    }

}


@media (max-width: 700px) {

    .student-dashboard {
        flex-direction: column;
    }

    .student-sidebar {
        width: 100%;
        min-width: 100%;
        min-height: auto;
    }

    .sidebar-title {
        padding: 18px;
    }

    .sidebar-item {
        display: inline-block;
        padding: 12px 15px;
    }

    .student-main {
        padding: 15px;
    }

    .page-header h1 {
        font-size: 23px;
    }

    .feedback-form-row {
        flex-direction: column;
        gap: 0;
    }

    .feedback-form-group {
        width: 100%;
    }

    .feedback-submit-button {
        width: 100%;
    }

    .card-header {
        align-items: flex-start;
        flex-direction: column;
    }

}


@media (max-width: 480px) {

    .student-main {
        padding: 10px;
    }

    .dashboard-card {
        padding: 15px;
    }

    .feedback-form-control {
        font-size: 13px !important;
    }

    .feedback-input-section h3 {
        font-size: 16px;
    }

    .feedback-submit-button {
        width: 100%;
    }

}

sp_widget.script:
(function() {

    // ==========================================
    // TEST USER
    // ==========================================

    var USER_ID =
        '82f46a0ea96b03107f444d1b3bf577cf';

    // Later:
    // var USER_ID = gs.getUserID();


    // ==========================================
    // INITIAL DATA
    // ==========================================

    data.userId = USER_ID;

    data.userName = '';

    data.kpi = {
        total: 0,
        pending: 0,
        resolved: 0
    };

    data.recentRequests = [];

    data.myRequests = [];

    data.feedbacks = {};

    data.feedbackCount = 0;

    data.selectedFeedback = null;

    data.messHalls = [];

    data.success = false;

    data.message = '';

    data.complaintNumber = '';

    data.complaintSysId = '';

    data.feedbackSuccess = false;

    data.feedbackMessage = '';


    // ==========================================
    // GET USER
    // ==========================================

    var userGR =
        new GlideRecord('sys_user');

    if (userGR.get(USER_ID)) {

        data.userName =
            userGR.getDisplayValue('name');

    }


    // ==========================================
    // LOAD MESS HALLS
    // ==========================================

    var messHallGR =
        new GlideRecord(
            'x_snc_campus_foo_1_mess_hall'
        );

    messHallGR.orderBy('name');

    messHallGR.query();

    while (messHallGR.next()) {

        data.messHalls.push({

            sys_id:
                messHallGR.getUniqueValue(),

            name:
                messHallGR.getDisplayValue('name')

        });

    }


    // ==========================================
    // CREATE FOOD COMPLAINT
    // ==========================================

    if (
        input &&
        input.action == 'createComplaint'
    ) {

        var complaintGR =
            new GlideRecord(
                'x_snc_campus_foo_1_food_complaint'
            );

        complaintGR.initialize();

        complaintGR.setValue(
            'student',
            USER_ID
        );

        complaintGR.setValue(
            'use_case',
            input.use_case
        );

        complaintGR.setValue(
            'mess_hall',
            input.mess_hall
        );

        complaintGR.setValue(
            'meal_type',
            input.meal_type
        );

        complaintGR.setValue(
            'problem_type',
            input.problem_type
        );

        complaintGR.setValue(
            'description',
            input.description
        );

        var complaintSysId =
            complaintGR.insert();


        if (complaintSysId) {

            data.success = true;

            data.complaintSysId =
                complaintSysId;

            data.complaintNumber =
                complaintGR.getValue('number');

            data.message =
                'Food complaint submitted successfully.';

        } else {

            data.success = false;

            data.message =
                'Unable to create food complaint.';

        }

    }


    // ==========================================
    // LOAD FOOD COMPLAINTS
    // ==========================================

    var complaintListGR =
        new GlideRecord(
            'x_snc_campus_foo_1_food_complaint'
        );

    complaintListGR.addQuery(
        'student',
        USER_ID
    );

    complaintListGR.orderByDesc(
        'sys_created_on'
    );

    complaintListGR.query();


    while (complaintListGR.next()) {

        var complaint = {

            sys_id:
                complaintListGR.getUniqueValue(),

            number:
                complaintListGR.getDisplayValue(
                    'number'
                ),

            use_case:
                complaintListGR.getDisplayValue(
                    'use_case'
                ),

            mess_hall:
                complaintListGR.getDisplayValue(
                    'mess_hall'
                ),

            meal_type:
                complaintListGR.getDisplayValue(
                    'meal_type'
                ),

            problem_type:
                complaintListGR.getDisplayValue(
                    'problem_type'
                ),

            description:
                complaintListGR.getDisplayValue(
                    'description'
                ),

            state:
                complaintListGR.getDisplayValue(
                    'state'
                ),

            created:
                complaintListGR.getDisplayValue(
                    'sys_created_on'
                )

        };


        data.myRequests.push(
            complaint
        );


        // ======================================
        // KPI
        // ======================================

        data.kpi.total++;


        var state =
            complaintListGR.getValue(
                'state'
            );


        if (
            state == '1' ||
            state == '2'
        ) {

            data.kpi.pending++;

        }


        if (
            state == '6' ||
            state == '7'
        ) {

            data.kpi.resolved++;

        }

    }


    // ==========================================
    // RECENT REQUESTS
    // ==========================================

    for (
        var i = 0;
        i < data.myRequests.length &&
        i < 5;
        i++
    ) {

        data.recentRequests.push(
            data.myRequests[i]
        );

    }


    // ==========================================
    // UPDATE FEEDBACK RECORD
    // ==========================================

    if (
        input &&
        input.action == 'submitFeedback'
    ) {

        var feedbackSysId =
            input.feedbackSysId;


        var feedbackUpdateGR =
            new GlideRecord(
                'x_snc_campus_foo_1_food_complaint_feedbacks'
            );


        // ======================================
        // FIND SAME RECORD USING SYS_ID
        // ======================================

        if (
            feedbackUpdateGR.get(
                feedbackSysId
            )
        ) {


            // ==================================
            // SECURITY CHECK
            // MAKE SURE RECORD BELONGS TO USER
            // ==================================

            if (
                feedbackUpdateGR.getValue(
                    'student'
                ) == USER_ID
            ) {


                // ==============================
                // OVERALL RATING
                // ==============================

                feedbackUpdateGR.setValue(
                    'overall_rating',
                    input.overall_rating
                );


                // ==============================
                // RESOLUTION SATISFACTION
                // ==============================

                feedbackUpdateGR.setValue(
                    'resolution_satisfaction',
                    input.resolution_satisfaction
                );


                // ==============================
                // FEEDBACK COMMENTS
                // ==============================

                feedbackUpdateGR.setValue(
                    'feedback_comments',
                    input.feedback_comments
                );


                // ==============================
                // MARK SUBMITTED
                // ==============================

                feedbackUpdateGR.setValue(
                    'feedback_submitted',
                    true
                );


                // ==============================
                // UPDATE SAME RECORD
                // ==============================

                feedbackUpdateGR.update();


                data.feedbackSuccess =
                    true;

                data.feedbackMessage =
                    'Feedback submitted successfully.';


            } else {


                data.feedbackSuccess =
                    false;

                data.feedbackMessage =
                    'You are not allowed to update this feedback record.';

            }


        } else {


            data.feedbackSuccess =
                false;

            data.feedbackMessage =
                'Feedback record not found.';

        }

    }


    // ==========================================
    // LOAD FEEDBACK RECORDS
    // ==========================================

    var feedbackGR =
        new GlideRecord(
            'x_snc_campus_foo_1_food_complaint_feedbacks'
        );


    feedbackGR.addQuery(
        'student',
        USER_ID
    );


    feedbackGR.addQuery(
        'feedback_submitted',
        false
    );


    feedbackGR.orderByDesc(
        'sys_created_on'
    );


    feedbackGR.query();


    while (feedbackGR.next()) {


        // ======================================
        // GET SYS ID
        // ======================================

        var feedbackSysId =
            feedbackGR.getUniqueValue();


        // ======================================
        // CREATE FEEDBACK OBJECT
        // ======================================

        var feedback = {

            number:
                feedbackGR.getDisplayValue(
                    'number'
                ),

            base_problem:
                feedbackGR.getDisplayValue(
                    'base_problem'
                ),

            meal_type:
                feedbackGR.getDisplayValue(
                    'meal_type'
                ),

            mess_hall:
                feedbackGR.getDisplayValue(
                    'mess_hall'
                ),

            problem_type:
                feedbackGR.getDisplayValue(
                    'problem_type'
                ),

            use_case:
                feedbackGR.getDisplayValue(
                    'use_case'
                ),

            student:
                feedbackGR.getDisplayValue(
                    'student'
                ),

            overall_rating:
                feedbackGR.getValue(
                    'overall_rating'
                ),

            resolution_satisfaction:
                feedbackGR.getValue(
                    'resolution_satisfaction'
                ),

            feedback_comments:
                feedbackGR.getValue(
                    'feedback_comments'
                ),

            state:
                feedbackGR.getDisplayValue(
                    'status'
                ),

            created:
                feedbackGR.getDisplayValue(
                    'sys_created_on'
                )

        };


        // ======================================
        // SYS_ID AS KEY
        // ======================================

        data.feedbacks[feedbackSysId] =
            feedback;


        // ======================================
        // COUNT
        // ======================================

        data.feedbackCount++;

    }

})();
